  const data=block.split('\n').filter(l=>l.startsWith('data:')).map(l=>l.slice(5).trimStart()).join('\n');if(!data)return;if(data.trim()==='[DONE]'){sawDone=true;return;}
  let event;try{event=JSON.parse(data);}catch{throw new Error(t('API 流式响应格式无效（不是合法 JSON）'));}if(event.error)throw new Error(event.error.message||t('API 流式错误'));
