function scrollBottom(){const c=$('#conversation');if(c)c.scrollTo({top:c.scrollHeight,behavior:'instant'});}
function retry(){if(state.streaming)return;const messages=[...current().messages];while(messages.at(-1)?.role==='assistant')messages.pop();send({regenerateMessages:messages});}
function regenerate(id){if(state.streaming)return toast(t('请先停止生成'));const i=current().messages.findIndex(m=>m.id===id);send({regenerateMessages:current().messages.slice(0,i)});}
function editMessage(id){if(state.streaming)return toast(t('请先停止生成'));const i=current().messages.findIndex(m=>m.id===id),m=current().messages[i];if(Array.isArray(m.content))return toast(t('带图片的消息请复制文字后重新发送'));openModal(t('编辑并重新生成'),ui`<div class="field"><textarea id="edit-text" style="min-height:180px">${esc(m.content)}</textarea></div><p class="hint">提交后会从这条消息重新生成，后续消息将移除。</p><div class="modal-footer">${button(t('取消'),'close-modal')}${button(t('重新生成'),'confirm','refresh','primary')}</div>`);$('[data-action="confirm"]',$('#modal-root')).onclick=()=>{const text=$('#edit-text').value.trim();if(!text)return;const messages=current().messages.slice(0,i);messages.push({...m,content:text});closeModal();send({regenerateMessages:messages});};}
function toolResult(){if(state.streaming)return toast(t('请等待当前生成结束'));const last=current().messages.at(-1);if(!last?.tool_calls?.length)return;openModal(t('提交工具执行结果'),last.tool_calls.map((t,i)=>ui`<div class="field"><label>${esc(t.function.name)}</label><pre class="raw-code">${esc(t.function.arguments)}</pre><textarea data-tool-index="${i}" placeholder="粘贴你执行此工具得到的结果"></textarea></div>`).join('')+`<div class="modal-footer">${button(t('取消'),'close-modal')}${button(t('提交并继续'),'confirm','send','primary')}</div>`);$('[data-action="confirm"]',$('#modal-root')).onclick=()=>{const results=$$('[data-tool-index]',$('#modal-root')).map(el=>el.value);if(results.some(v=>!v.trim()))return toast(t('请填写所有工具的执行结果'));const messages=[...current().messages,...last.tool_calls.map((t,i)=>({id:uid(),role:'tool',content:results[i],tool_call_id:t.id}))];closeModal();send({regenerateMessages:messages});};}
async function manageModel(id,forceLoad=false){if(state.preview)return toast(t('演示模式下不可用'));if(!state.native)return toast(t('未检测到 LM Studio 原生管理接口'));if(state.streaming)return toast(t('请先停止生成再管理模型'));if(state.busyModel)return;const m=state.models.find(m=>m.id===id);if(forceLoad&&m?.loaded)return toast(t('模型已加载，请先卸载'));state.busyModel=id;if(state.page==='models')renderPage();const base=state.profile.nativeUrl||state.profile.baseUrl;try{if(m?.loaded&&!forceLoad){for(const instance of m.instances)await api('/api/v1/models/unload',{instance_id:instance.id},{base});toast(t('模型已卸载'));}else{const p=state.params;const payload={model:id,echo_load_config:true};for(const key of loadKeys)if(p['override_'+key]&&(key!=='num_experts'||p.num_experts>0))payload[key]=p[key];await api('/api/v1/models/load',payload,{base});toast(t('模型加载成功'));}const data=await api('/api/v1/models',null,{base});state.models=normalizeModels(data,true);state.model=id;current().model=id;if(shared.record)applySharedRecord(shared.record);renderMetrics();}catch(e){toast(e.message);}finally{state.busyModel='';save();render();}}
function downloadModal(){if(!state.native||state.preview)return toast(t('模型下载接口不可用'));openModal(t('下载模型'),ui`<div class="field"><label>模型目录 ID 或 Hugging Face 链接</label><input id="download-model-id" placeholder="openai/gpt-oss-20b"></div><div class="field"><label>量化</label><input id="download-quant" placeholder="Q4_K_M"></div><div class="modal-footer">${button(t('取消'),'close-modal')}${button(t('开始下载'),'confirm','download','primary')}</div>`);$('[data-action="confirm"]',$('#modal-root')).onclick=async()=>{const model=$('#download-model-id').value.trim(),quantization=$('#download-quant').value.trim();if(!model)return toast(t('请输入模型 ID 或链接'));const b=$('[data-action="confirm"]',$('#modal-root'));b.disabled=true;try{const job=await api('/api/v1/models/download',{model,...(quantization?{quantization}:{})},{base:state.profile.nativeUrl||state.profile.baseUrl});state.jobs.unshift({...job,model});closeModal();go('models');toast(t('已提交服务端下载任务'));}catch(e){toast(e.message);b.disabled=false;}};}
async function refreshJob(id){const j=state.jobs.find(j=>j.job_id===id);try{Object.assign(j,await api('/api/v1/models/download/status/'+encodeURIComponent(id),null,{base:state.profile.nativeUrl||state.profile.baseUrl}));j.percent=j.total_size_bytes?Math.round(j.downloaded_bytes/j.total_size_bytes*100):null;renderPage();}catch(e){toast(e.message);}}
function embeddingsModal(){if(!state.connected||state.preview)return toast(t('请先连接 API'));const models=state.models.filter(m=>m.type==='embedding');openModal(t('嵌入接口测试'),ui`<div class="field"><label>嵌入模型</label><select id="embedding-model">${models.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select></div>${!models.length?t('<p class="hint">模型列表中未发现嵌入模型。</p>'):''}<div class="field"><label>输入文本</label><textarea id="embedding-input" placeholder="输入文本"></textarea></div>${button(t('生成嵌入'),'embed','code','primary')}<div id="embedding-result"></div>`);$('[data-action="embed"]',$('#modal-root')).onclick=async e=>{const model=$('#embedding-model').value,input=$('#embedding-input').value;if(!model||!input.trim())return toast(t('请选择嵌入模型并填写文本'));e.currentTarget.disabled=true;try{const result=await api('/v1/embeddings',{model,input});$('#embedding-result').innerHTML=ui`<div class="hint" style="margin-top:15px">维度：${result.data?.[0]?.embedding?.length||0}</div><pre class="raw-code">${esc(JSON.stringify(result,null,2))}</pre>`;}catch(error){toast(error.message);}finally{$('[data-action="embed"]',$('#modal-root')).disabled=false;}};}
function exportData(all){const data={format:'lumen-studio',version:1,chats:all?state.chats:[current()],exported:new Date().toISOString()};download(JSON.stringify(data,null,2),all?'lumen-all-chats.json':'lumen-'+current().title+'.json');}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name.replace(/[<>:"/\\|?*]/g,'-');a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast(t('已复制'));}catch{toast(t('浏览器禁止剪贴板访问，请手动选择复制'));}}
$('#file-input').onchange=async e=>{const files=[...e.target.files];try{if(state.attachments.length+files.length>6)throw new Error(t('每条消息最多 6 个附件'));for(const file of files){if(file.size>8*1024**2)throw new Error(t('单个附件不能超过 8 MB'));if(file.type.startsWith('image/')){if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw new Error(t('图片请使用 PNG、JPEG、WebP 或 GIF'));const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});state.attachments.push({name:file.name,type:'image',data});}else{if(file.size>200000)throw new Error(t('文本附件请控制在 200 KB 内'));state.attachments.push({name:file.name,type:'text',data:await file.text()});}}state.draft=$('#prompt')?.value||'';renderPage();}catch(error){toast(error.message);}finally{e.target.value='';}};
$('#import-input').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>20*1024**2)throw new Error(t('备份文件过大'));const data=JSON.parse(await file.text());if(data.format!=='lumen-studio'||!Array.isArray(data.chats)||!data.chats.every(c=>typeof c.title==='string'&&Array.isArray(c.messages)))throw new Error(t('不是有效的 Lumen Studio 会话备份'));const chats=data.chats.map(c=>({id:uid(),title:c.title.slice(0,100),created:Number(c.created)||Date.now(),model:typeof c.model==='string'?c.model:'',params:{...defaults,...Object.fromEntries(Object.entries(c.params||{}).filter(([k])=>k in defaults))},messages:c.messages.filter(m=>['user','assistant','tool','system'].includes(m.role)).map(m=>({...m,id:uid(),content:typeof m.content==='string'?m.content:Array.isArray(m.content)?m.content.filter(p=>p.type==='text'&&typeof p.text==='string'||p.type==='image_url'&&/^data:image\/(?:png|jpeg|webp|gif);base64,/.test(p.image_url?.url||'')):''}))}));state.chats.unshift(...chats);if(chats.length)state.active=chats[0].id;state.params={...defaults,...current().params};save();go('chat');toast(ui`已导入 ${chats.length} 个对话`);}catch(error){toast(error.message);}finally{e.target.value='';}};
function startDemo(){if(state.streaming)return toast(t('请先停止生成'));state.preview=true;state.connected=true;state.native=false;state.latency=0;state.models=[{id:'demo/local-model',name:t('界面演示模型'),type:'llm',params:'—',loaded:false,native:false}];state.model='demo/local-model';state.inspector=true;go('chat');toast(t('已进入演示模式'));}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#shell')?.classList.remove('show-sidebar','show-inspector');}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='n'){e.preventDefault();$('[data-action="new-chat"]')?.click();}if(e.key==='Tab'&&$('.modal')){const items=$$('button,input,textarea,select,a[href]',$('.modal')).filter(el=>!el.disabled&&el.offsetParent!==null);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});
window.addEventListener('beforeunload',()=>{if(state.streaming)state.controller?.abort();flushSave(true);});

function modelIdentity(){try{return state.connected&&state.model&&!state.preview?JSON.stringify([normalizeBase(state.profile.baseUrl),state.model]):'';}catch{return '';}}
function hostLoadConfig(){const model=state.models.find(m=>m.id===state.model);const instance=model?.instances?.find(i=>i.id===state.model)||model?.instances?.[0];return Object.fromEntries(loadKeys.filter(k=>instance?.config?.[k]!==undefined).map(k=>[k,instance.config[k]]));}
function sharedBanner(){
 const available=!!modelIdentity(),labels={idle:t('未连接'),loading:t('读取中'),synced:shared.record?.revision?'v'+shared.record.revision:t('默认'),dirty:t('待同步'),saving:t('同步中'),conflict:t('冲突'),error:t('失败')};
 return ui`<section class="shared-config" id="shared-config-status"><div class="row between"><strong class="small">${icon('globe')} 共享参数</strong><span class="badge ${shared.status==='synced'?'green':''}">${esc(labels[shared.status]||labels.idle)}</span></div>${available?`<div class="row shared-actions">${button(t('刷新'),'refresh-config','refresh','ghost')}${button(t('导入'),'import-config','upload','ghost')}${!shared.record?.revision?button(t('共享'),'publish-config','globe','ghost'):''}</div>`:''}${shared.error?`<p class="hint" style="color:var(--red)">${esc(shared.error)}</p>`:''}${shared.status==='conflict'?`<div class="row shared-actions">${button(t('采用共享版本'),'accept-shared','refresh')}${button(t('保留修改'),'overwrite-shared','upload')}</div>`:shared.status==='error'&&Object.keys(shared.dirty).length?button(t('重试'),'overwrite-shared','refresh'):''}</section>`;
}
function renderSharedBanner(){const el=$('#shared-config-status');if(el)el.outerHTML=sharedBanner();}
async function configRequest(method='GET',data){const source=normalizeBase(state.profile.baseUrl),model=state.model;const response=await fetch('/api/model-config'+(method==='GET'?'?'+new URLSearchParams({source,model}):''),{method,headers:{'Content-Type':'application/json'},body:method==='GET'?undefined:JSON.stringify({source,model,...data}),signal:AbortSignal.timeout(10000)});let result;try{result=await response.json();}catch{throw new Error(t('共享配置不可用，请重启服务'));}if(!response.ok&&response.status!==409)throw new Error(localizeError(result.error)||t('无法访问共享配置服务'));return {status:response.status,...result};}
function applySharedRecord(record){shared.record=record;const effective={...defaults,...hostLoadConfig(),...record.params,...shared.dirty};shared.effective={...effective};state.params=effective;current().params={...effective};save();syncParameterControls();renderSharedBanner();renderMetrics();}
function syncParameterControls(){for(const el of $$('[data-param]')){const value=state.params[el.dataset.param];if(document.activeElement===el)continue;if(el.type==='checkbox')el.checked=!!value;else el.value=el.type==='number'?parameterValue(el.dataset.param):value??'';if(configurableParams.includes(el.dataset.param))el.disabled=!state.params['override_'+el.dataset.param];}for(const el of $$('[data-range]'))if(document.activeElement!==el){el.value=state.params[el.dataset.range];el.disabled=!state.params['override_'+el.dataset.range];}for(const b of $$('[data-override]')){const enabled=!!state.params['override_'+b.dataset.override];b.classList.toggle('overridden',enabled);b.setAttribute('aria-pressed',String(enabled));b.textContent=enabled?t('恢复默认'):Object.hasOwn(hostLoadConfig(),b.dataset.override)?t('自定义'):t('自定义');}}
async function activateModelConfig(force=false){
 const id=modelIdentity();if(!id){renderSharedBanner();return false;}
 if(shared.id===id&&shared.record&&!force){applySharedRecord(shared.record);return true;}
 if(shared.id!==id){clearTimeout(sharedTimer);shared={id,record:null,remote:null,dirty:{},baseline:{},effective:{},status:'loading',error:'',saving:false};}else shared.status='loading';renderSharedBanner();
 try{const result=await configRequest();if(id!==modelIdentity()||id!==shared.id)return false;shared.status='synced';shared.error='';applySharedRecord(result.record);return true;}catch(e){if(shared.id===id){shared.status='error';shared.error=e.message;renderSharedBanner();}return false;}
}
function scheduleSharedSave(){
 if(!modelIdentity()||shared.id!==modelIdentity()||!shared.record)return;
 for(const key of Object.keys(defaults)){if(state.params[key]!==shared.effective[key]){if(!Object.hasOwn(shared.baseline,key))shared.baseline[key]=shared.record.params[key];shared.dirty[key]=state.params[key];shared.effective[key]=state.params[key];}}
 if(!Object.keys(shared.dirty).length)return;
 shared.status=shared.status==='conflict'?'conflict':'dirty';shared.error='';renderSharedBanner();clearTimeout(sharedTimer);if(shared.status!=='conflict')sharedTimer=setTimeout(()=>flushShared(),500);
}
async function flushShared(force=false){
 clearTimeout(sharedTimer);if(!Object.keys(shared.dirty).length)return true;
 if(shared.saving)return false;if(shared.status==='conflict'&&!force)return false;
 const identity=shared.id,patch={...shared.dirty},baseline={...shared.baseline};shared.saving=true;shared.status='saving';renderSharedBanner();
 try{let result=await configRequest('PATCH',{revision:shared.record?.revision||0,patch});if(identity!==shared.id)return false;
  if(result.status===409){const conflict=Object.keys(patch).some(k=>JSON.stringify(result.record.params[k])!==JSON.stringify(baseline[k]));if(conflict&&!force){shared.remote=result.record;shared.status='conflict';shared.error=t('配置冲突');return false;}shared.record=result.record;result=await configRequest('PATCH',{revision:result.record.revision,patch});if(identity!==shared.id)return false;if(result.status===409){shared.remote=result.record;shared.status='conflict';shared.error=t('配置已更新，请重试');return false;}}
  for(const k of Object.keys(patch))if(shared.dirty[k]===patch[k]){delete shared.dirty[k];delete shared.baseline[k];}
  shared.status=Object.keys(shared.dirty).length?'dirty':'synced';shared.error='';shared.remote=null;applySharedRecord(result.record);return true;
 }catch(e){if(identity===shared.id){shared.status='error';shared.error=e.message;}return false;}
 finally{if(identity===shared.id){shared.saving=false;renderSharedBanner();if(shared.status==='dirty')sharedTimer=setTimeout(()=>flushShared(),300);}}
}
async function pullShared(){if(!modelIdentity()||shared.id!==modelIdentity()||shared.saving||shared.status==='loading')return;const id=shared.id;try{const result=await configRequest();if(id!==shared.id||id!==modelIdentity())return;if(result.record.revision!==(shared.record?.revision||0)){if(Object.keys(shared.dirty).length){shared.remote=result.record;const conflicts=Object.keys(shared.dirty).some(k=>JSON.stringify(result.record.params[k])!==JSON.stringify(shared.baseline[k]));if(conflicts){shared.status='conflict';shared.error=t('配置冲突');renderSharedBanner();}else{shared.record=result.record;applySharedRecord(result.record);}}else{shared.status='synced';shared.error='';applySharedRecord(result.record);}}else if(shared.status==='error'&&!Object.keys(shared.dirty).length){shared.status='synced';shared.error='';applySharedRecord(result.record);}}catch(e){if(id===shared.id&&shared.status!=='conflict'){shared.status='error';shared.error=e.message;renderSharedBanner();}}}
async function publishCurrentConfig(){if(!modelIdentity())return toast(t('请先连接并选择模型'));if(!shared.record&&!(await activateModelConfig()))return;for(const key of Object.keys(defaults)){shared.baseline[key]=shared.record.params[key];shared.dirty[key]=state.params[key];}shared.status='dirty';if(await flushShared())toast(t('参数已共享'));}
let hostRefreshAt=0,hostRefreshing=false;
async function refreshHostConfig(silent=false){if(!state.native||!state.connected||state.preview){if(!silent)toast(t('当前接口未开放 LM Studio 原生模型信息'));return;}if(hostRefreshing)return;hostRefreshing=true;const identity=modelIdentity();try{const result=await api('/api/v1/models',null,{base:state.profile.nativeUrl||state.profile.baseUrl,signal:AbortSignal.timeout(8000)});if(identity!==modelIdentity())return;state.models=normalizeModels(result,true);hostRefreshAt=Date.now();if(shared.record)applySharedRecord(shared.record);else{state.params={...state.params,...hostLoadConfig()};syncParameterControls();renderMetrics();}if(!silent)toast(t('配置已更新'));}catch(e){if(!silent)toast(e.message);}finally{hostRefreshing=false;}}
function latestAssistant(){const messages=current().messages;for(let i=messages.length-1;i>=0;i--)if(messages[i].role==='assistant')return messages[i];}
function receptionLabel(message){const stats=receptionStats(message);return `${stats.exact?'':'≈ '}${stats.tokens.toLocaleString()} tokens${stats.exact?'':t('（估算）')}`;}
function conversationReceived(){let tokens=0,exact=true;for(const message of current().messages)if(message.role==='assistant'){const stats=receptionStats(message);tokens+=stats.tokens;exact=exact&&stats.exact;}return `${exact?'':'≈ '}${tokens.toLocaleString()} tokens`;}
function thinkingDockHTML(){const m=latestAssistant();if(!m||(!state.streaming&&!m.reasoning&&!m.interrupted&&m.status!=='truncated'))return '';return ui`<section class="thinking-dock" data-message="${m.id}" aria-label="模型接收状态"><div class="row between"><span class="row"><span class="activity-dot ${state.streaming?'active':''}"></span><strong class="thinking-status"></strong><small class="thinking-elapsed muted"></small></span><button class="thinking-expand" data-action="show-thinking">展开思考 ${icon('chevron')}</button></div><div class="thinking-preview"></div><div class="thinking-reception muted"></div></section>`;}
function renderThinkingDock(){
 const slot=$('#thinking-slot');if(!slot)return;const m=latestAssistant(),show=m&&(state.streaming||m.reasoning||m.interrupted||m.status==='truncated');if(!show){slot.innerHTML='';return;}
 if($('.thinking-dock',slot)?.dataset.message!==m.id)slot.innerHTML=thinkingDockHTML();const dock=$('.thinking-dock',slot);if(!dock)return;
 const live=state.streaming&&m.status==='pending';const status=m.status==='truncated'?t('输出达到接口限制'):m.status==='interrupted'?t('连接中断 · 内容已保留'):m.status==='stopped'?t('已停止生成'):live?(m.tool_calls?.length?t('正在接收工具调用'):m.thinking||m.reasoning&&!m.content?t('模型正在思考'):m.content?t('正在接收回答'):m.receivedBytes?t('接收中'):m.connectedAt?t('等待输出'):t('等待响应')):m.status==='reasoning_only'?t('仅返回思考'):t('思考已完成');
 $('.thinking-status',dock).textContent=status;$('.activity-dot',dock).classList.toggle('active',live);
 $('.thinking-elapsed',dock).textContent=(live?Math.max(0,(Date.now()-(m.startedAt||m.created))/1000).toFixed(0):((m.ms||0)/1000).toFixed(1))+' s';
 $('.thinking-expand',dock).hidden=!m.reasoning;
 const preview=(m.reasoningPreview??m.reasoning?.slice(-240))?.replace(/\s+/g,' ').trim();dock.dataset.collapsed=String(!live||!m.thinking);$('.thinking-preview',dock).hidden=!(live&&m.thinking);$('.thinking-preview',dock).textContent=preview?preview.slice(-200):m.errorInfo|| (live?t('等待输出…'):t('无思考内容'));
 const received=receptionStats(m);$('.thinking-reception',dock).textContent=ui`已接收 ${receptionLabel(m)} · ${received.chars.toLocaleString()} 字符 · ${received.events.toLocaleString()} 个流事件`+(live&&m.lastActivityAt?' · '+Math.max(0,Math.floor((Date.now()-m.lastActivityAt)/1000))+t(' 秒前收到数据'):'');
}
function showThinking(){const m=latestAssistant();if(!m?.reasoning)return;m.reasoningOpen=true;let detail=$(`[data-reasoning-id="${m.id}"]`);if(!detail){renderPage();detail=$(`[data-reasoning-id="${m.id}"]`);}if(detail){detail.open=true;populateReasoning(detail,m);const c=$('#conversation');c.scrollTo({top:c.scrollTop+detail.getBoundingClientRect().top-c.getBoundingClientRect().top-20,behavior:'instant'});}}
function captureReasoningUI(){for(const detail of $$('.reasoning')){const m=current().messages.find(m=>m.id===detail.dataset.reasoningId);if(m){m.reasoningOpen=detail.open;m.reasoningScroll=$('pre',detail)?.scrollTop||0;}}}
function completionNotice(m){if(m.role!=='assistant')return '';let text='';if(m.status==='truncated')text=ui`输出未完成 · ${m.finishReason||'length'}`;else if(m.interrupted)text=m.errorInfo||t('连接中断');else if(m.status==='reasoning_only')text=t('仅返回思考');else if(m.finishReason==='content_filter')text=t('输出已停止 · content_filter');return text?`<div class="completion-notice" role="status">${icon('info')}<div class="grow">${esc(text)}</div>${!state.streaming?button(t('继续生成'),'continue-output','send'):''}</div>`:'';}
function continueOutput(){if(state.streaming||state.preparing)return;const m=latestAssistant();if(!m)return;const messages=[...current().messages];messages.push({id:uid(),role:'user',content:m.content?t('请从上一次中断的位置继续完成回答，不要重复已经输出的内容。'):t('请继续完成原问题，并给出最终回答。'),created:Date.now()});send({regenerateMessages:messages});}
document.addEventListener('toggle',event=>{const detail=event.target;if(!detail.matches?.('details.reasoning'))return;const m=current().messages.find(m=>m.id===detail.dataset.reasoningId);if(m){m.reasoningOpen=detail.open;if(detail.open)populateReasoning(detail,m);else{const pre=$('pre',detail);pre.replaceChildren();pre.dataset.renderedLength='0';}}},true);
document.addEventListener('scroll',event=>{const pre=event.target;if(!pre.matches?.('.reasoning pre'))return;const m=current().messages.find(m=>m.id===pre.closest('.reasoning').dataset.reasoningId);if(m)m.reasoningScroll=pre.scrollTop;},true);
setInterval(()=>{if(state.streaming&&document.visibilityState!=='hidden')renderThinkingDock();},1000);
function usageStats(usage){if(!usage)return {cached:null,prompt:null,total:null};const n=value=>typeof value==='number'&&Number.isFinite(value)&&value>=0?value:null;const prompt=n(usage.prompt_tokens??usage.input_tokens),out=n(usage.completion_tokens??usage.output_tokens);return {cached:n(usage.prompt_tokens_details?.cached_tokens??usage.input_tokens_details?.cached_tokens??usage.prompt_cache_hit_tokens??usage.cache_read_input_tokens??usage.cached_tokens),prompt,total:n(usage.total_tokens)??(prompt!==null&&out!==null?prompt+out:null)};}
function metricValues(){const message=[...current().messages].reverse().find(m=>m.role==='assistant'&&!m.error&&(!state.model||m.model===state.model)),usage=usageStats(message?.usage);const actual=hostLoadConfig();const model=state.models.find(m=>m.id===state.model);const cache=usage.cached===null?t('未返回'):usage.cached.toLocaleString()+' tokens'+(usage.prompt>0?' · '+(usage.cached/usage.prompt*100).toFixed(1)+'%':'');const used=usage.total===null?t('未返回'):usage.total.toLocaleString();const window=actual.context_length?actual.context_length.toLocaleString()+' tokens':state.connected?t('服务端未返回'):t('等待连接');return {cache,used,window,context:actual.context_length||null,multiple:(model?.instances?.length||0)>1};}
function metricsHTML(){const m=metricValues();return ui`<div class="request-metrics" id="request-metrics" aria-live="polite"><span class="current-received" title="输出用量">已接收 <b>${receptionLabel(latestAssistant())}</b></span><span title="累计用量">对话累计 <b>${conversationReceived()}</b></span><span title="缓存命中">${icon('bolt')}缓存命中 <b>${esc(m.cache)}</b></span><span title="输入和输出用量">本次用量 <b>${esc(m.used)}</b></span><span title="上下文窗口${m.multiple?t(' · 首个实例'):''}">窗口 <b>${esc(m.window)}${m.multiple?t(' · 多实例'):''}</b></span></div>`;}
function renderMetrics(){const el=$('#request-metrics');if(el)el.outerHTML=metricsHTML();}
function importModelConfig(){if(!modelIdentity())return toast(t('请先连接模型'));const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>2*1024**2)throw new Error(t('预设文件请控制在 2 MB 内'));const parsed=JSON.parse(await f.text());const params=parseModelPreset(parsed);if(!Object.keys(params).length)throw new Error(t('预设里没有识别到可同步的参数'));openModal(t('导入并共享模型配置'),`<p class="hint"></p><pre class="raw-code">${esc(JSON.stringify(params,null,2))}</pre><div class="modal-footer">${button(t('取消'),'close-modal')}${button(t('发布这些参数'),'confirm','upload','primary')}</div>`);$('.modal [data-action="confirm"]').onclick=async()=>{if(!shared.record&&!(await activateModelConfig()))return;for(const [key,value]of Object.entries(params)){shared.baseline[key]=shared.record.params[key];shared.dirty[key]=value;}shared.status='dirty';closeModal();if(await flushShared()){toast(t('预设已导入并共享'));renderInspector();}};}catch(e){toast(e.message);}};input.click();}
function parseModelPreset(data){
 const out={};const direct=data.params||data;if(direct&&typeof direct==='object')for(const k of Object.keys(defaults))if(Object.hasOwn(direct,k)&&typeof direct[k]===typeof defaults[k])out[k]=direct[k];
 const mapping={'llm.prediction.temperature':'temperature','llm.prediction.topPSampling':'top_p','llm.prediction.topKSampling':'top_k','llm.prediction.repeatPenalty':'repeat_penalty','llm.prediction.presencePenalty':'presence_penalty','llm.prediction.frequencyPenalty':'frequency_penalty','llm.prediction.maxPredictedTokens':'max_tokens','llm.prediction.seed':'seed','llm.prediction.stopStrings':'stop','llm.prediction.systemPrompt':'system','llm.load.contextLength':'context_length','llm.load.evalBatchSize':'eval_batch_size','llm.load.flashAttention':'flash_attention','llm.load.offloadKVCacheToGpu':'offload_kv_cache_to_gpu','llm.load.numExperts':'num_experts'};
 for(const obj of [data,data.operation,data.load,data.perChatPredictionConfig,data.globalPredictionConfig]){const fields=Array.isArray(obj)?obj:obj?.fields;if(!Array.isArray(fields))continue;for(const f of fields){const key=mapping[f.key];if(!key)continue;let value=f.value;if(value&&typeof value==='object'&&!Array.isArray(value)){if(value.checked===false||value.enabled===false)continue;value=value.value;}if(key==='stop'&&Array.isArray(value))value=value.join('\n');if(key==='max_tokens'&&value===-1)value=0;if(typeof value===typeof defaults[key])out[key]=value;}}
 if(typeof data.systemPrompt==='string')out.system=data.systemPrompt;
 for(const name of configurableParams)if(Object.hasOwn(out,name)&&!Object.hasOwn(out,'override_'+name))out['override_'+name]=name==='max_tokens'?out.max_tokens>0:true;
 return out;
}
setInterval(()=>{if(document.visibilityState==='hidden')return;pullShared();if(Date.now()-hostRefreshAt>15000&&!state.streaming)refreshHostConfig(true);},3000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')pullShared();});
render();
if(state.profile.baseUrl)setTimeout(()=>discover(true),100);
